      {remaining > 0 && (
        <div
          className="-ml-1 flex h-5 w-5 items-center justify-center rounded-[4px] bg-background text-[8px] font-medium text-muted-foreground shadow-minimal"
          style={{ zIndex: display.length + 1 }}
