/**
 * Project Storage
 *
 * CRUD operations for workspace-scoped projects.
 * Projects are stored at {workspaceRootPath}/projects/{projectSlug}/
 *
 * Note: All functions take `workspaceRootPath` (absolute path to workspace folder),
 * NOT a workspace slug. The `LoadedProject.workspaceId` is derived via basename().
 */

import {
  existsSync,
  mkdirSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
  unlinkSync,
  readFileSync,
} from 'fs';
import { basename, extname, join } from 'path';
import { randomUUID } from 'crypto';
import { atomicWriteFileSync, readJsonFileSync, getMimeType } from '../utils/files.ts';
import { generateUniqueSlug } from '../utils/slug.ts';
import { debug } from '../utils/debug.ts';
import { expandPath, toPortablePath } from '../utils/paths.ts';
import { estimateTokensDensityAware } from '../utils/large-response.ts';
import type {
  ProjectConfig,
  ProjectAsset,
  LoadedProject,
  CreateProjectInput,
} from './types.ts';

// ============================================================
// Directory Utilities
// ============================================================

/**
 * Get path to workspace projects directory.
 */
export function getWorkspaceProjectsPath(workspaceRootPath: string): string {
  return join(workspaceRootPath, 'projects');
}

/**
 * Get path to a project folder within a workspace.
 */
export function getProjectPath(workspaceRootPath: string, projectSlug: string): string {
  return join(getWorkspaceProjectsPath(workspaceRootPath), projectSlug);
}

/**
 * Get path to a project's assets directory.
 */
export function getProjectAssetsPath(workspaceRootPath: string, projectSlug: string): string {
  return join(getProjectPath(workspaceRootPath, projectSlug), 'assets');
}

/** Filename of a project's agent-maintained "lessons learned" doc. */
export const MEMORY_FILENAME = 'MEMORY.md';

/**
 * Get path to a project's MEMORY.md. Deliberately a sibling of config.json
 * (outside assets/) so it never shows up in the asset manifest.
 */
export function getProjectMemoryPath(workspaceRootPath: string, projectSlug: string): string {
  return join(getProjectPath(workspaceRootPath, projectSlug), MEMORY_FILENAME);
}

/**
 * Ensure projects directory exists for a workspace.
 */
export function ensureProjectsDir(workspaceRootPath: string): void {
  const dir = getWorkspaceProjectsPath(workspaceRootPath);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

/**
 * Ensure a project's assets directory exists.
 */
export function ensureProjectAssetsDir(workspaceRootPath: string, projectSlug: string): void {
  const dir = getProjectAssetsPath(workspaceRootPath, projectSlug);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

// ============================================================
// Config Operations
// ============================================================

/**
 * Load project config.json.
 * Returns null if the config does not exist or fails to parse.
 */
export function loadProjectConfig(
  workspaceRootPath: string,
  projectSlug: string,
): ProjectConfig | null {
  const configPath = join(getProjectPath(workspaceRootPath, projectSlug), 'config.json');
  if (!existsSync(configPath)) return null;

  try {
    const config = readJsonFileSync<ProjectConfig>(configPath);

    // Expand portable paths on read so consumers always see absolute paths.
    if (config.workingDirectory) {
      config.workingDirectory = expandPath(config.workingDirectory);
    }

    return config;
  } catch (error) {
    debug('[loadProjectConfig] Failed to read project config:', projectSlug, error);
    return null;
  }
}

/**
 * Save project config.json (atomic write, bumps updatedAt).
 */
export function saveProjectConfig(workspaceRootPath: string, config: ProjectConfig): void {
  const dir = getProjectPath(workspaceRootPath, config.slug);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }

  const storageConfig: ProjectConfig = {
    ...config,
    updatedAt: Date.now(),
  };

  if (storageConfig.workingDirectory) {
    storageConfig.workingDirectory = toPortablePath(storageConfig.workingDirectory);
  }

  atomicWriteFileSync(join(dir, 'config.json'), JSON.stringify(storageConfig, null, 2));
}

// ============================================================
// Memory Operations
// ============================================================

/**
 * Load a project's MEMORY.md, capped at `maxTokens` for prompt injection.
 *
 * Returns `null` when the file is missing or effectively empty. When the
 * content exceeds the budget it is **head-truncated** (the top is kept, since
 * the agent is instructed to write newest/most-important first) and a one-line
 * marker is appended. The returned string — marker included — stays within the
 * token budget.
 */
export function loadProjectMemory(
  workspaceRootPath: string,
  projectSlug: string,
  maxTokens = 5000,
): string | null {
  const memoryPath = getProjectMemoryPath(workspaceRootPath, projectSlug);
  if (!existsSync(memoryPath)) return null;

  let content: string;
  try {
    content = readFileSync(memoryPath, 'utf-8');
  } catch (error) {
    debug('[loadProjectMemory] Failed to read MEMORY.md:', projectSlug, error);
    return null;
  }

  if (!content.trim()) return null;

  const tokens = estimateTokensDensityAware(content);
  if (tokens <= maxTokens) return content;

  // Over budget: reserve room for the marker, then head-truncate. `charsPerToken`
  // is derived from the actual content so a density-corrected estimate (base64-heavy
  // memory) still maps back to a sensible character budget.
  const marker = `\n\n…[MEMORY.md truncated at ${maxTokens}-token cap — keep it shorter]`;
  const markerTokens = estimateTokensDensityAware(marker);
  const bodyBudget = Math.max(0, maxTokens - markerTokens);
  const charsPerToken = content.length / tokens;
  const charBudget = Math.floor(bodyBudget * charsPerToken);
  const head = content.slice(0, charBudget).trimEnd();
  return `${head}${marker}`;
}

// ============================================================
// Load Operations
// ============================================================

/**
 * Load a single project by slug.
 */
export function loadProject(
  workspaceRootPath: string,
  projectSlug: string,
): LoadedProject | null {
  const config = loadProjectConfig(workspaceRootPath, projectSlug);
  if (!config) return null;

  const folderPath = getProjectPath(workspaceRootPath, projectSlug);
  const assetsPath = getProjectAssetsPath(workspaceRootPath, projectSlug);
  const workspaceId = basename(workspaceRootPath);

  return {
    config,
    folderPath,
    assetsPath,
    workspaceRootPath,
    workspaceId,
  };
}

/**
 * Load a project by id (scans workspace projects for a matching id).
 * Slugs are unique within a workspace, but callers may persist the project id
 * on a session (more stable across renames).
 */
export function loadProjectById(
  workspaceRootPath: string,
  projectId: string,
): LoadedProject | null {
  const projects = loadWorkspaceProjects(workspaceRootPath);
  return projects.find((p) => p.config.id === projectId) ?? null;
}

/**
 * Load all projects for a workspace.
 */
export function loadWorkspaceProjects(workspaceRootPath: string): LoadedProject[] {
  ensureProjectsDir(workspaceRootPath);

  const projects: LoadedProject[] = [];
  const projectsDir = getWorkspaceProjectsPath(workspaceRootPath);

  if (!existsSync(projectsDir)) return projects;

  const entries = readdirSync(projectsDir, { withFileTypes: true });
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const project = loadProject(workspaceRootPath, entry.name);
    if (project) projects.push(project);
  }

  return projects;
}

// ============================================================
// Create / Update / Delete
// ============================================================

/**
 * Generate a URL-safe, workspace-unique project slug.
 */
export function generateProjectSlug(workspaceRootPath: string, name: string): string {
  const projectsDir = getWorkspaceProjectsPath(workspaceRootPath);
  const existingSlugs = new Set<string>();
  if (existsSync(projectsDir)) {
    for (const entry of readdirSync(projectsDir, { withFileTypes: true })) {
      if (entry.isDirectory()) existingSlugs.add(entry.name);
    }
  }
  return generateUniqueSlug(name, existingSlugs, 'project');
}

/**
 * Create a new project in a workspace.
 */
export function createProject(
  workspaceRootPath: string,
  input: CreateProjectInput,
): ProjectConfig {
  const slug = generateProjectSlug(workspaceRootPath, input.name);
  const now = Date.now();

  const config: ProjectConfig = {
    id: `proj_${randomUUID().slice(0, 8)}`,
    slug,
    name: input.name,
    description: input.description,
    workingDirectory: input.workingDirectory,
    details: input.details,
    colorTheme: input.colorTheme,
    createdAt: now,
    updatedAt: now,
  };

  saveProjectConfig(workspaceRootPath, config);
  ensureProjectAssetsDir(workspaceRootPath, slug);

  return config;
}

/**
 * Update a project's config with a partial patch.
 * `id` and `slug` cannot be changed.
 */
export function updateProject(
  workspaceRootPath: string,
  projectSlug: string,
  patch: Partial<Omit<ProjectConfig, 'id' | 'slug' | 'createdAt'>>,
): ProjectConfig {
  const existing = loadProjectConfig(workspaceRootPath, projectSlug);
  if (!existing) {
    throw new Error(`Project not found: ${projectSlug}`);
  }

  const updated: ProjectConfig = {
    ...existing,
    ...patch,
    id: existing.id,
    slug: existing.slug,
    createdAt: existing.createdAt,
    updatedAt: Date.now(),
  };

  saveProjectConfig(workspaceRootPath, updated);
  return updated;
}

/**
 * Delete a project (removes folder and all assets).
 * Caller is responsible for unsetting `projectId` on sessions that referenced it.
 */
export function deleteProject(workspaceRootPath: string, projectSlug: string): void {
  const dir = getProjectPath(workspaceRootPath, projectSlug);
  if (existsSync(dir)) {
    rmSync(dir, { recursive: true });
  }
}

/**
 * Check if a project exists in a workspace.
 */
export function projectExists(workspaceRootPath: string, projectSlug: string): boolean {
  return existsSync(join(getProjectPath(workspaceRootPath, projectSlug), 'config.json'));
}

// ============================================================
// Asset Operations
// ============================================================

/**
 * Sanitize an upload filename so it stays inside the assets directory.
 * Strips path separators and leading dots; falls back to a uuid name if empty.
 */
export function sanitizeAssetFilename(filename: string): string {
  // Strip path separators AND control chars (NUL/newlines/DEL) so a crafted upload name can't
  // escape the assets dir or, once listed, forge new lines in the <project_assets> prompt block.
  // eslint-disable-next-line no-control-regex
  const base = basename(filename).replace(/[\\/\x00-\x1f\x7f]+/g, '').replace(/^\.+/, '');
  if (!base) return `asset_${randomUUID().slice(0, 8)}`;
  return base.slice(0, 255);
}

/**
 * List all assets for a project (sorted newest first).
 */
export function listProjectAssets(
  workspaceRootPath: string,
  projectSlug: string,
): ProjectAsset[] {
  ensureProjectAssetsDir(workspaceRootPath, projectSlug);

  const assetsDir = getProjectAssetsPath(workspaceRootPath, projectSlug);
  if (!existsSync(assetsDir)) return [];

  const assets: ProjectAsset[] = [];
  for (const entry of readdirSync(assetsDir, { withFileTypes: true })) {
    if (!entry.isFile()) continue;
    const filePath = join(assetsDir, entry.name);
    try {
      const stats = statSync(filePath);
      assets.push({
        filename: entry.name,
        sizeBytes: stats.size,
        mimeType: getMimeType(filePath),
        uploadedAt: stats.mtimeMs,
        absolutePath: filePath,
      });
    } catch (error) {
      debug('[listProjectAssets] Failed to stat asset:', filePath, error);
    }
  }

  assets.sort((a, b) => b.uploadedAt - a.uploadedAt);
  return assets;
}

export interface UploadProjectAssetInput {
  filename: string;
  /** Base64-encoded contents (preferred for cross-process IPC) */
  base64?: string;
  /** Raw text contents (for small text/markdown uploads) */
  text?: string;
  /** Absolute source path on disk; copied into the assets folder */
  sourcePath?: string;
}

/**
 * Upload (write) an asset into the project's assets directory.
 * Accepts base64, text, or a sourcePath to copy from.
 * Resolves filename collisions by appending `-{n}` before the extension.
 */
export function uploadProjectAsset(
  workspaceRootPath: string,
  projectSlug: string,
  input: UploadProjectAssetInput,
): ProjectAsset {
  if (!projectExists(workspaceRootPath, projectSlug)) {
    throw new Error(`Project not found: ${projectSlug}`);
  }

  ensureProjectAssetsDir(workspaceRootPath, projectSlug);

  const safeName = sanitizeAssetFilename(input.filename);
  const assetsDir = getProjectAssetsPath(workspaceRootPath, projectSlug);
  const targetPath = resolveUniqueAssetPath(assetsDir, safeName);

  if (input.base64 !== undefined) {
    writeFileSync(targetPath, Buffer.from(input.base64, 'base64'));
  } else if (input.text !== undefined) {
    writeFileSync(targetPath, input.text, 'utf-8');
  } else if (input.sourcePath) {
    if (!existsSync(input.sourcePath)) {
      throw new Error(`Source file does not exist: ${input.sourcePath}`);
    }
    const data = readFileSync(input.sourcePath);
    writeFileSync(targetPath, data);
  } else {
    throw new Error('uploadProjectAsset requires one of: base64, text, sourcePath');
  }

  const stats = statSync(targetPath);
  return {
    filename: basename(targetPath),
    sizeBytes: stats.size,
    mimeType: getMimeType(targetPath),
    uploadedAt: stats.mtimeMs,
    absolutePath: targetPath,
  };
}

/**
 * Delete a single asset from a project (no-op if missing).
 */
export function deleteProjectAsset(
  workspaceRootPath: string,
  projectSlug: string,
  filename: string,
): void {
  const safe = sanitizeAssetFilename(filename);
  const target = join(getProjectAssetsPath(workspaceRootPath, projectSlug), safe);
  if (!existsSync(target)) return;

  // Refuse to follow path traversal — `safe` should already be the bare filename.
  if (basename(target) !== safe) {
    throw new Error(`Refusing to delete asset outside assets directory: ${filename}`);
  }

  try {
    unlinkSync(target);
  } catch (error) {
    debug('[deleteProjectAsset] Failed to delete asset:', target, error);
    throw error;
  }
}

/**
 * Resolve a target path inside `assetsDir` that does not collide with existing files.
 * Returns the original name if free; otherwise appends `-2`, `-3`, ... before the extension.
 */
function resolveUniqueAssetPath(assetsDir: string, filename: string): string {
  const candidate = join(assetsDir, filename);
  if (!existsSync(candidate)) return candidate;

  const ext = extname(filename);
  const stem = ext ? filename.slice(0, -ext.length) : filename;

  let counter = 2;
  while (existsSync(join(assetsDir, `${stem}-${counter}${ext}`))) counter++;
  return join(assetsDir, `${stem}-${counter}${ext}`);
}

/**
 * Decision layer — settings model (browser-safe: no Node imports).
 *
 * Stored under `StoredConfig.decisionLayer` (see config/storage.ts
 * `getDecisionLayerSettings` / `setDecisionLayerSettings`). Everything is
 * optional on disk; `normalizeDecisionLayerSettings` fills the defaults.
 *
 * The layer is OFF by default; the `enabled` switch in Settings > AI is the only
 * master gate (no environment flag).
 */

import {
  DecisionError,
  DECISION_DEFAULT_DEADLINE_MS,
  DECISION_MAX_DEADLINE_MS,
  DECISION_MIN_DEADLINE_MS,
  isDecisionProviderId,
  type DecisionProviderId,
} from './types.ts';
import { DECISION_PROVIDER_PRESETS, buildSystemOneEndpoint, type DecisionProviderPreset } from './providers.ts';

/**
 * Which product surfaces may call the decision model. All zero-authority: an
 * answer can add friction or information, never remove a prompt.
 */
export interface DecisionLayerFeatureToggles {
  /** `decide` session tool (agent-initiated classification / routing / scoring). */
  decideTool: boolean;
  /** Typed task verdicts when the orchestrator's text has no parseable verdict. */
  taskVerdicts: boolean;
  /** Semantic auto-label rules next to regex rules. */
  semanticLabels: boolean;
  /** How a turn ended (finished / needs input / blocked): Needs Review status, task nodes not marked done. */
  turnOutcome: boolean;
  /**
   * Offer the Guarded permission mode: runs like Execute, but a non-read-only call the model
   * judges risky becomes a prompt (adds prompts, never removes them). Execute never asks the model.
   */
  guardedMode: boolean;
  /** Risk badges on permission prompts (informational). */
  riskBadges: boolean;
  /** Automation `semanticCondition`: skip a prompt run whose condition the model answers below its threshold. */
  automationConditions: boolean;
  /** Repair only the subtasks a FAIL verdict's reason implicates (when it names none). */
  taskRepairs: boolean;
  /** Skip titling small talk; refresh automatic titles that no longer fit. */
  smartTitles: boolean;
  /** Lower the thinking level for a simple turn (never above the session's). */
  adaptiveThinking: boolean;
  /** Mid-turn messages: steer corrections, queue follow-ups, merge queued continuations. */
  midTurnMessages: boolean;
  /** Skip the summary of a large tool result when the preview and saved file are enough. */
  largeResults: boolean;
  /** Point the agent at a skill or inactive source the user's message plainly needs. */
  suggestions: boolean;
}

export type DecisionLayerFeature = keyof DecisionLayerFeatureToggles;

export const DECISION_LAYER_FEATURES: readonly DecisionLayerFeature[] = [
  'decideTool',
  'taskVerdicts',
  'semanticLabels',
  'turnOutcome',
  'guardedMode',
  'riskBadges',
  'automationConditions',
  'taskRepairs',
  'smartTitles',
  'adaptiveThinking',
  'midTurnMessages',
  'largeResults',
  'suggestions',
] as const;

export interface DecisionLayerSettings {
  /** Master switch. Off → the app behaves exactly as without the layer. */
  enabled: boolean;
  provider: DecisionProviderId;
  /**
   * Reuse the API key of an existing LLM connection (OpenRouter or Vercel AI
   * Gateway). When set, the provider is derived from that connection.
   */
  connectionSlug?: string;
  /** Required for `custom`; optional override for the presets. */
  baseUrl?: string;
  /** Pinned model id; defaults to the provider preset. */
  model?: string;
  /** Wall-clock budget per call for background features. The `decide` tool uses its own. */
  deadlineMs: number;
  features: DecisionLayerFeatureToggles;
}

/** On-disk shape: everything optional. */
export interface DecisionLayerStoredSettings {
  enabled?: boolean;
  provider?: DecisionProviderId;
  connectionSlug?: string;
  baseUrl?: string;
  model?: string;
  deadlineMs?: number;
  features?: Partial<DecisionLayerFeatureToggles>;
}

/** Patch accepted by `setDecisionLayerSettings`: `null` clears an optional string. */
export interface DecisionLayerSettingsPatch {
  enabled?: boolean;
  provider?: DecisionProviderId;
  connectionSlug?: string | null;
  baseUrl?: string | null;
  model?: string | null;
  deadlineMs?: number;
  features?: Partial<DecisionLayerFeatureToggles>;
}

export const DEFAULT_DECISION_LAYER_SETTINGS: DecisionLayerSettings = {
  enabled: false,
  provider: 'typesafe',
  deadlineMs: DECISION_DEFAULT_DEADLINE_MS,
  // The first three only act when invoked (agent tool call, unparsed verdict, a semantic rule
  // exists); the harness features change what the app does on their own, so they start off.
  features: { decideTool: true, taskVerdicts: true, semanticLabels: true, turnOutcome: false, guardedMode: false, riskBadges: false, automationConditions: false, taskRepairs: false, smartTitles: false, adaptiveThinking: false, midTurnMessages: false, largeResults: false, suggestions: false },
};

function cleanString(value: unknown): string | undefined {
  if (typeof value !== 'string') return undefined;
  const trimmed = value.trim();
  return trimmed ? trimmed : undefined;
}

function cleanDeadline(value: unknown): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return DECISION_DEFAULT_DEADLINE_MS;
  return Math.min(DECISION_MAX_DEADLINE_MS, Math.max(DECISION_MIN_DEADLINE_MS, Math.round(value)));
}

/** Fill defaults, drop garbage. Safe on `undefined`/`null`/partial input. */
export function normalizeDecisionLayerSettings(stored?: DecisionLayerStoredSettings | null): DecisionLayerSettings {
  const source = stored ?? {};
  const defaults = DEFAULT_DECISION_LAYER_SETTINGS;
  const features: DecisionLayerFeatureToggles = { ...defaults.features };
  for (const feature of DECISION_LAYER_FEATURES) {
    const value = source.features?.[feature];
    if (typeof value === 'boolean') features[feature] = value;
  }

  const settings: DecisionLayerSettings = {
    enabled: source.enabled === true,
    provider: isDecisionProviderId(source.provider) ? source.provider : defaults.provider,
    deadlineMs: cleanDeadline(source.deadlineMs),
    features,
  };
  const connectionSlug = cleanString(source.connectionSlug);
  if (connectionSlug) settings.connectionSlug = connectionSlug;
  const baseUrl = cleanString(source.baseUrl);
  if (baseUrl) settings.baseUrl = baseUrl;
  const model = cleanString(source.model);
  if (model) settings.model = model;
  return settings;
}

/**
 * Merge a patch over the stored value. `null` clears an optional string; features merge key-wise.
 * Returns the stored (sparse) shape so unknown future keys on disk are preserved.
 *
 * Changing the provider (directly, or by choosing a connection) drops the
 * `baseUrl` and `model` overrides unless the same patch sets them: they belong
 * to the previous provider, and a stale custom base URL would otherwise
 * receive the new provider's key.
 */
export function mergeDecisionLayerSettings(
  current: DecisionLayerStoredSettings | undefined,
  patch: Partial<Record<keyof DecisionLayerStoredSettings, unknown>>,
): DecisionLayerStoredSettings {
  const next: DecisionLayerStoredSettings = { ...(current ?? {}) };

  const previousProvider = current?.provider ?? DEFAULT_DECISION_LAYER_SETTINGS.provider;
  const providerChanged = isDecisionProviderId(patch.provider) && patch.provider !== previousProvider;
  const connectionChanged = 'connectionSlug' in patch && (cleanString(patch.connectionSlug) ?? undefined) !== current?.connectionSlug;
  if (providerChanged || connectionChanged) {
    delete next.baseUrl;
    delete next.model;
  }

  if (typeof patch.enabled === 'boolean') next.enabled = patch.enabled;
  if (isDecisionProviderId(patch.provider)) next.provider = patch.provider;
  if (typeof patch.deadlineMs === 'number') next.deadlineMs = cleanDeadline(patch.deadlineMs);

  for (const key of ['connectionSlug', 'baseUrl', 'model'] as const) {
    if (!(key in patch)) continue;
    const value = patch[key];
    if (value === null || value === '') delete next[key];
    else {
      const cleaned = cleanString(value);
      if (cleaned) next[key] = cleaned;
    }
  }

  if (patch.features && typeof patch.features === 'object') {
    const merged: Partial<DecisionLayerFeatureToggles> = { ...(next.features ?? {}) };
    for (const feature of DECISION_LAYER_FEATURES) {
      const value = (patch.features as Record<string, unknown>)[feature];
      if (typeof value === 'boolean') merged[feature] = value;
    }
    next.features = merged;
  }

  return next;
}

export interface ResolvedDecisionEndpoint {
  provider: DecisionProviderId;
  preset: DecisionProviderPreset;
  baseUrl: string;
  endpoint: string;
  model: string;
  extraHeaders: Record<string, string>;
}

/**
 * Turn settings into a concrete endpoint. `providerOverride` is used when the
 * key comes from an LLM connection (the connection decides the provider).
 * Throws `DecisionError('unconfigured')` for `custom` without a base URL.
 */
export function resolveDecisionEndpoint(settings: DecisionLayerSettings, providerOverride?: DecisionProviderId): ResolvedDecisionEndpoint {
  const provider = providerOverride ?? settings.provider;
  const preset = DECISION_PROVIDER_PRESETS[provider];
  const baseUrl = settings.baseUrl ?? preset.baseUrl;
  if (!baseUrl) {
    throw new DecisionError('unconfigured', 'Decision model: a base URL is required for the custom provider');
  }
  let endpoint: string;
  try {
    endpoint = buildSystemOneEndpoint(baseUrl);
    // eslint-disable-next-line no-new
    new URL(endpoint);
  } catch {
    throw new DecisionError('unconfigured', 'Decision model: the base URL is not a valid URL');
  }
  return {
    provider,
    preset,
    baseUrl,
    endpoint,
    model: settings.model ?? preset.defaultModel,
    extraHeaders: { ...(preset.extraHeaders ?? {}) },
  };
}

/**
 * Decision layer — local server probe.
 *
 * `laya-serve` (and many Jev-compatible clones) expose `GET /health`. The
 * Settings card uses this to tell the user whether their local server is up
 * and which checkpoints it has loaded. Best effort: never throws, short
 * timeout, no auth (health endpoints are unauthenticated on laya-serve).
 */

import { readDecisionLayerSettings } from './resolve.ts';
import { DECISION_PROVIDER_PRESETS } from './providers.ts';
import type { DecisionLayerSettings } from './settings.ts';
import type { DecisionProviderId } from './types.ts';

export const DECISION_PROBE_TIMEOUT_MS = 2_000;

export interface DecisionServerProbe {
  provider: DecisionProviderId;
  baseUrl: string;
  /** The URL that was requested. */
  url: string;
  /** TCP+HTTP round trip succeeded (any status). */
  reachable: boolean;
  status?: number;
  /** Parsed `laya-serve` health body when the server returned one. */
  health?: { status?: string; loaded?: string[]; device?: string };
  /** Safe to show: never contains a key. */
  message?: string;
  latencyMs: number;
}

function joinUrl(baseUrl: string, path: string): string {
  return `${baseUrl.trim().replace(/\/+$/, '')}${path.startsWith('/') ? path : `/${path}`}`;
}

/** Probe a Jev-compatible server's health endpoint. Never throws. */
export async function probeDecisionServer(
  provider: DecisionProviderId,
  baseUrl: string,
  options: { fetch?: typeof globalThis.fetch; timeoutMs?: number; healthPath?: string } = {},
): Promise<DecisionServerProbe> {
  const fetchImpl = options.fetch ?? globalThis.fetch;
  const healthPath = options.healthPath ?? DECISION_PROVIDER_PRESETS[provider].healthPath ?? '/health';
  const startedAt = performance.now();
  let url: string;
  try {
    url = joinUrl(baseUrl, healthPath);
    // eslint-disable-next-line no-new
    new URL(url);
  } catch {
    return { provider, baseUrl, url: baseUrl, reachable: false, message: 'Base URL is not a valid URL', latencyMs: 0 };
  }

  try {
    const response = await fetchImpl(url, { method: 'GET', signal: AbortSignal.timeout(options.timeoutMs ?? DECISION_PROBE_TIMEOUT_MS) });
    const latencyMs = Math.round(performance.now() - startedAt);
    const probe: DecisionServerProbe = { provider, baseUrl, url, reachable: true, status: response.status, latencyMs };
    if (response.ok) {
      try {
        const body = (await response.json()) as Record<string, unknown>;
        if (body && typeof body === 'object') {
          probe.health = {
            ...(typeof body.status === 'string' ? { status: body.status } : {}),
            ...(Array.isArray(body.loaded) ? { loaded: body.loaded.filter((x): x is string => typeof x === 'string') } : {}),
            ...(typeof body.device === 'string' ? { device: body.device } : {}),
          };
        }
      } catch {
        probe.message = 'Server is up but its health endpoint did not return JSON';
      }
    } else if (response.status === 404) {
      probe.message = 'Server is reachable but has no health endpoint';
    } else {
      probe.message = `Health endpoint answered HTTP ${response.status}`;
    }
    return probe;
  } catch (error) {
    const latencyMs = Math.round(performance.now() - startedAt);
    const name = error instanceof Error ? error.name : '';
    const message = name === 'TimeoutError' || name === 'AbortError'
      ? `No answer within ${options.timeoutMs ?? DECISION_PROBE_TIMEOUT_MS} ms`
      : 'Could not connect';
    return { provider, baseUrl, url, reachable: false, message, latencyMs };
  }
}

/** Probe the server the current settings point at (a local preset or a custom base URL). */
export async function probeConfiguredDecisionServer(
  settings: DecisionLayerSettings = readDecisionLayerSettings(),
  options: { fetch?: typeof globalThis.fetch; timeoutMs?: number; baseUrlOverride?: string } = {},
): Promise<DecisionServerProbe> {
  const preset = DECISION_PROVIDER_PRESETS[settings.provider];
  const baseUrl = options.baseUrlOverride?.trim() || settings.baseUrl || preset.baseUrl;
  if (!baseUrl) {
    return { provider: settings.provider, baseUrl: '', url: '', reachable: false, message: 'No base URL configured', latencyMs: 0 };
  }
  return probeDecisionServer(settings.provider, baseUrl, { fetch: options.fetch, timeoutMs: options.timeoutMs });
}
